examples.setupTemplate:
@State private var status = MonarchAiComputerViewStatus.{{status|raw}}

private static func placeholder() -> Image {
    // A neutral stand-in for a sign-in page, as the web example draws it: a header bar, a card, two fields and a button.
    let context = CGContext(
        data: nil, width: 240, height: 150, bitsPerComponent: 8, bytesPerRow: 0,
        space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    func fill(_ gray: CGFloat, _ x: CGFloat, _ y: CGFloat, _ width: CGFloat, _ height: CGFloat, radius: CGFloat = 0) {
        context.setFillColor(gray: gray, alpha: 1)
        let rect = CGRect(x: x / 4, y: 150 - (y + height) / 4, width: width / 4, height: height / 4)
        context.addPath(CGPath(roundedRect: rect, cornerWidth: radius / 4, cornerHeight: radius / 4, transform: nil))
        context.fillPath()
    }
    fill(1, 0, 0, 960, 600)
    fill(0.88, 0, 0, 960, 64)
    fill(0.94, 330, 150, 300, 300, radius: 12)
    fill(0.86, 370, 210, 220, 36, radius: 6)
    fill(0.86, 370, 270, 220, 36, radius: 6)
    fill(0.5, 370, 350, 220, 44, radius: 8)
    return Image(decorative: context.makeImage()!, scale: 1)
}

